   "text": "最后一章不总结定理，它给判据。\n先给一句话结论：**审美动机可以是发现的向导，但绝不能当作真理的凭证；在缺少数据的时候，唯一可用的判据是「这条论断依赖哪些尚未观测的假设」。**\n这句话不是修辞，前面三十三章各出现过一次。第 1 章把「数学真理靠证明、物理真理靠实验」这条界线立起来；第 31 章用它去审查弦论；第 32 章用它提醒「框架内的离散不等于自然界的离散」；第 33 章用它给扭量理论一个克制的自我评价。这一章要做的，是把那把尺子说成一句你能带走的话。\n本章还有第二个任务：回到开头那三个世界与三个谜。第一个谜（数学为什么能描述物理）整本书都在给它找线索，它没有被解决，但被提得精确多了。第二个谜（物理如何产生心智）明确留在书外。第三个谜（心智如何通达数学）顺带触及。\n最后一节是全书的态度：**深问题被解答了，更深的问题被提出来。** 这不是失败，这是诚实的形状。"
