   "orig": "这与第 31–33 章所述那些把量子理论与引力结合起来的一种种尝试相比，反差极大——就后者而言，如今的（或可合理设想的）实验状况要差得多。为检验这类量子引力提案而设计的实验，绝大多数都要用以高得离谱的能量抛出的粒子，远非任何现有（或认真规划中的）加速器所能及。（据我所知只有两类例外：一类是检验「大」额外维度（31.4 节）是否存在的实验，比如看它会不会在小距离上改动引力的平方反比律；另一类是一些关系松散的提案，想看看高能下洛伦兹协变性会不会因设想的量子引力效应而破缺。）「常规的」量子引力方案确实面临一个根本困难：这种结合所产生的效应只改时空结构，且只在极其微小的普朗克距离或时间上起作用，量子力学的标准程序则原封不动。反过来，如果像第 30 章所设想的那样，是广义相对论的效应去修改量子力学的规则，实验处境就好得多，因为这些预期效应大体上落在现有技术能够到的范围内。这类实验一旦做成，并且表明量子力学的规则确实需要改动，我们才终于有了实实在在的物理指引，去补足目前驱动量子引力研究的那些多半只是数学上的诉求。",
