    {
     "q": "「这种结合所产生的效应只改时空结构」",
     "a": "这是「常规」方案的共同骨架：量子力学照旧，只把引力换成量子版本，效应压在普朗克尺度上。作者点出它的要害——效应小到无法探测，理论也就几乎无法被实验触及。"
    }
