   "h": "34.2 数学驱动的基础物理",
   "orig": "数学观念与物理行为之间的相互作用，是贯穿本书的一条线索。纵观物理科学史，进步总是靠在两者之间找准平衡：一边是数学理论的约束、诱惑与启示，另一边是对物理世界行为的精确观察——通常经由精心控制的实验。而当实验指引缺席时——当前大多数基础研究正是如此——这个平衡就失了准。数学上的自洽远不足以告诉我们是否「走在正道上」（许多时候，连这条看似必需的要求也被抛到九霄云外）。于是我们看到，数学上的审美价值开始扮演比以往大得多的角色。研究者常常举狄拉克、薛定谔、爱因斯坦、费曼以及许多别人的成功为例，说他们在相当程度上是被自己所提出的那些理论观念的审美吸引力牵着走的。依我看，这类审美考虑的价值无可否认；在为基础物理挑选可信的新理论时，它们起着根本性的作用。",
