   "orig": "历史上这样的例子很多：一个优美的数学方案起初像是提供了揭示自然奥秘的革命性新途径，结果那些最初的希望并没有兑现——至少没有按当初设想的方式兑现。四元数就是一个好例子，说的正是它构成可除代数这一美妙性质。正如 11.2 节所说，哈密顿 1843 年发现四元数之后，被它诱着把余生 22 年都投进了「把自然律完全写进这个框架」的努力。然而这套「纯四元数」的工作（我指的是他最初那套真正的四元数，连同它的可除代数性质）对基础物理科学后来的发展几乎没有直接影响。哈密顿对物理理论的其他影响当然巨大，而且相当直接：正是他早年对如今称作「哈密顿量」「哈密顿原理」「哈密顿–雅可比方程」等等东西的研究——那是对牛顿粒子与波之类比的一次探索——成了 20 世纪量子力学与 QFT 发展的起跳点（见 20.2 节及 21.1、2 节）。四元数对物理的影响却是远的，要经由那些不得不抛弃可除代数性质的推广才传递过来。",
