   "orig": "读者看得出来，我在本书里给这些理论各分配多少篇幅，只是很松散地照顾了一下时尚的要求。（弯曲时空中的 QFT 与霍金效应有关，我在 30.4 节简略提过。格点方法用离散的时空模型代替连续模型——见 33.1 节。欧几里得量子引力出现在 28.9 节讨论的霍金进路里。量子宇宙学用的是把大多数引力自由度都略去的简化时空。其余几种进路在第 31–33 章讨论过。）值得注意的是，弦论一家的文章数就超过了其他所有领域的总和。普遍的看法似乎是：今天若重做这项统计，弦论的优势还要更大。假如把科学研究想成按民主政府的原则来办，那么由于弦论家占了绝对多数，该做什么研究就全由他们说了算！",
