   "h": "34.3 时尚在物理理论中的角色",
   "orig": "还有一点也成立：就像商业机构一样，大的天然地倾向于以小的为代价继续做大。科学时尚里为何也会如此，不难明白，尤其在这个喷气旅行加互联网的时代：新的科学想法迅速传遍全球，或者在会议上口耳相传，或者经由电子邮件和网络，以（常常未经审稿的）论文形式几乎即时地传开。交流如此便利，竞争便往往变得近乎疯狂，于是出现「随大流」效应：研究者生怕不跟进就被甩在后面。对于那些不断受到实验检验的理论想法，时尚未必成多大问题；但对于像量子引力这样远离「可被实验证实或否证」之可能的想法，我们就得格外小心，不能把一个进路的走红当成它有效的真正标志。",
