   "h": "34.3 时尚在物理理论中的角色",
   "orig": "时尚在别的地方也有它的作用，比如记号或特定的数学形式系统。这也许不如上面那些问题重要，但对研究的发展仍有分量。举一个具体的例子：狄拉克的 4 分量旋量形式系统被极其普遍地使用，而范德瓦尔登后来那套 2 分量形式系统却少人问津（见 22.8、24.7、25.2 节）。这件事颇有点讽刺，下文便见分晓。事实上，在量子电动力学里，4 旋量形式系统几乎人人都在用；可正如罗伯特·杰罗奇（Robert Geroch）所表明的，用 2 旋量（22.8 节有简述）其实要简单得多。狄拉克 1928 年发现他的方程时用的就是 4 旋量。他的方程激起了人们对旋量重要性的极大兴趣；一年之后，杰出的荷兰数学家巴特尔·L·范德瓦尔登（Bartel L. van der Waerden）建立起了强有力的 2 旋量演算。可到那时，狄拉克发现电子方程所引起的轰动已经让多数物理学家跟着狄拉克的原始做法走，不少人甚至根本不知道范德瓦尔登那套更灵活、更精炼的形式系统。尽管如此，狄拉克本人似乎最终还是看出了范德瓦尔登所做工作的分量。20 世纪 50 年代初，我听过他的一门课，课上他对 2 旋量演算作了漂亮的介绍，把这门此前我读到的讲法几乎完全讲不通的学问一下子讲清楚了。",
