   "h": "34.3 时尚在物理理论中的角色",
   "orig": "狄拉克从不追逐时尚，甚至似乎并不总追随他自己立下的时尚！可别人有时会在并不情愿的情况下被卷进去。20 世纪 70 年代中期我去 CERN 与布鲁诺·祖米诺（Bruno Zumino）交谈，就碰上了这样一个例子——祖米诺是超对称某些基本思想的创始者之一。（他与尤利乌斯·威斯 1974 年的那项工作与扭量理论确有联系，我本想探个究竟。）他告诉我，他很清楚 2 旋量形式系统的长处，还曾写过一篇论文，用 2 旋量表述自己的某个想法。可是几个月后，据他说，德高望重的阿卜杜斯·萨拉姆提出了同样的想法，用的是 4 旋量。于是人人引萨拉姆那篇，没人引他那篇。祖米诺的结论是：今后再不犯这种错——不用那套（技术上更优越的）2 旋量形式系统了！",
