   "orig": "再者，即便只盯着宇宙可直接观测的那部分，我们也可以问：假定在大尺度上均匀且各向同性的空间几何，其曲率是正、是负还是零（即 K>0、K<0、K=0 三种情形；见 27.8 节）。若理论断言 K=0，它就具备观测上可反驳的品格：因为对空间平坦性的任何有限偏离，只要观测足够精确，原则上（尽管也许实际上做不到）总能辨认出来，无论那点空间曲率多小。但若理论断言 K≠0，而实际上 K=0，这个理论就无法被反驳，因为观测总带着一段不确定范围，足以容纳极微小的正曲率或负曲率。我们还注意到：K>0 的情形，若实际上 K<0，原则上可被反驳；K<0 的情形，若实际上 K>0，也可被反驳。反过来，K=0 不能被（直接）确认，而 K≠0 则可以在观测上得到确认（如果宇宙恰是这样）。于是 K>0 与 K<0 这两种断言，都在一种受限的意义上合乎波普尔：它们在特定情形下可被反驳（尽管实际若 K=0 就反驳不了），而且各自都有可能被确认。至于 K=0，原则上是十足的波普尔式，却无法被确认！",
