   "orig": "但数学观念真的栖居在一个属于它们自己的「世界」里吗？若是，那我们似乎发现，终极实在竟然安家在那样一个完全抽象的世界上。有些人难以接受把柏拉图的数学世界当作任何意义上的「实在」，而「物理实在本身只是由抽象观念构造出来的」这种看法也让他们得不到安慰。我自己在这件事上的立场是：我们当然应当承认，柏拉图的世界给了数学观念一种「实在性」（我在 1.3 节曾为此力辩）；但若真要去柏拉图的抽象实在里指认物理实在，我就要迟疑了。图 34.1 大概最能表达我的立场：柏拉图数学的、物理的、心智的三个世界，各自有其自身的实在性，而每一个都（深深地、神秘地）奠基于它前面那一个之上（三个世界首尾相接）。我倒愿意认为，柏拉图的世界也许是三者中最原初的，因为数学带有一种必然性，几乎单凭逻辑就把自己召唤出来。话虽如此，这些世界的循环相接还另有更深的谜，甚至悖论：每一个似乎都能把接在它后面的那个整个包进来，而它自己似乎只依赖前一个的一小部分。",
