   "orig": "古希腊人「是数学在支撑物理实在的运作」这一洞见，对我们极为管用。我希望自己已经讲清楚：尽管离既定目标尚远，我们对于宇宙在最深层次上的运作，已经达到了一种相当惊人的理解。有些数学概念在以往格外成功，颇为突出。其中之一是实数系统，另一个是几何的观念。几何起初是欧几里得几何，由古希腊人最先系统研究；后来观念从欧几里得一路走到兰伯特、高斯、罗巴切夫斯基、鲍耶、黎曼、贝尔特拉米等人的几何。再往后，闵可夫斯基教我们把时间与空间合在一起，爱因斯坦则把那宏伟的弯曲时空几何——广义相对论——交到我们手上。阿基米德、费马、牛顿、莱布尼茨、欧拉、柯西、嘉当以及许多别人的积分与微分演算，连同微分方程、积分方程、变分导数这些相关观念，对描述世界运作的那些成功理论来说已被证明绝对不可少；而这些观念又以极为要紧的方式与几何联系了起来。同样根本的，是那些使我们能处理由巨量个体成分构成的大型复杂物理系统的统计观念——麦克斯韦、玻尔兹曼、吉布斯、爱因斯坦等人都教过我们。",
