   "orig": "然而我们不妨一问：这些方案里那无可置疑的数学之美，若没有它们与宇宙运作如此契合这一非凡事实，是否还能作为纯数学独自放光？单拿它们当数学结构，去与纯数学里那些明珠、那些灯塔相比，又当如何？我相信它们会站得相当稳，但并非压倒性地稳。纯数学里有许多分支与物理世界看不出任何关系，其美却与我们迄今遇到的物理理论相当，甚至过之。（另见 16.2 节。）",
