   "h": "34.9 美与奇迹",
   "orig": "且看数学中一些深刻而美丽的发展，它们对物理的影响迄今微乎其微。康托的无穷理论就是一个值得注意的例子。依我看，它是整个数学史上最美、最深刻的贡献之一。然而就我们所知，它与物理世界的运作几乎毫无关系（见 16.3、4、7 节）。同样的问题也出现在数学理解的另一座丰碑上——哥德尔那著名的不完备性定理（16.6 节），它可以看作康托无穷理论的一个近亲。还有范畴论（33.1 节）那些广泛而深刻的想法，迄今与物理的联系也相当少。这后两个领域倒有些说得过去的迹象，显示它们可能与 21 世纪将会发展起来的物理有要紧关系（34.7 节、33.1 节），但这纯属揣测。至于绝大多数其他深刻而美丽的数学理论，要与物理发生重要联系，看来就远没有那么可信了。譬如 20 世纪安德鲁·怀尔斯的那项非凡成就：他证实了那个悬了三百五十多年的断言，即「费马大定理」。就我们今天所理解的物理定律而言，这离得极远，尽管其中用到的数学思想极为宏丽。20 世纪还有许多精彩的发展，比如单群的分类，连续的与离散的都算。这里确实有物理上的应用，但这远不等于说单群理论给了我们一门「物理理论」；只是说，数学上的分类能帮物理学家看清有哪些可能性。再看一例：19 世纪黎曼那精妙的 ζ 函数理论，以及它与素数分布的关系。这似乎同样远离物理，尽管至今未被证明的黎曼假设（7.4 节）有着无可置疑的美与极大的数学重要性。事实上，这里确有一些与物理的有趣联系，但要说黎曼的理论给了我们任何近似于物理世界模型的东西，那很难成立。",
